// Builds www/ (the Capacitor webDir) from src/: copies the web app and bundles
// Leaflet locally (unpkg CDN -> vendor/leaflet, offline-safe). Only the files
// the app loads are bundled: leaflet.js, leaflet.css and images/ (no leaflet-src*.js,
// *.esm.js or source maps). www/ is generated: do not edit it, it is git-ignored.
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), src = path.join(root, 'src'), www = path.join(root, 'www');
const lf = path.join(root, 'node_modules/leaflet/dist');
if (!fs.existsSync(lf)) { console.error('Run "npm install" first (Leaflet missing).'); process.exit(1); }

// Optional TomTom key for live traffic: QFLOW_TOMTOM_KEY, else the git-ignored file
// .tomtom-key in the project folder. Never stored in src/; written only to www/local-config.js.
const ttFile = path.join(root, '.tomtom-key');
const ttKey = (process.env.QFLOW_TOMTOM_KEY || (fs.existsSync(ttFile) ? fs.readFileSync(ttFile, 'utf8') : '')).trim();
if (ttKey && !/^[A-Za-z0-9_-]{16,64}$/.test(ttKey)) { console.error('QFLOW_TOMTOM_KEY does not look like a TomTom API key.'); process.exit(1); }

fs.rmSync(www, { recursive: true, force: true });
fs.mkdirSync(path.join(www, 'vendor/leaflet'), { recursive: true });
for (const f of fs.readdirSync(src)) {
  if (!/\.(html|css|js)$/.test(f)) continue;
  let t = fs.readFileSync(path.join(src, f), 'utf8');
  t = t.replace(/https:\/\/unpkg\.com\/leaflet@1\.9\.4\/dist\//g, 'vendor/leaflet/');
  fs.writeFileSync(path.join(www, f), t);
}
fs.writeFileSync(path.join(www, 'local-config.js'),
  '// Generated by npm run build:www. Do not edit or commit.\n' +
  'window.QFLOW_CONFIG = Object.assign(window.QFLOW_CONFIG || {}, ' + JSON.stringify(ttKey ? { tomtomKey: ttKey } : {}) + ');\n');
if (ttKey) console.log('Live traffic: TomTom key (' + (process.env.QFLOW_TOMTOM_KEY ? 'QFLOW_TOMTOM_KEY' : '.tomtom-key') + ') included in www/local-config.js (it will be inside the APK).');
for (const f of ['leaflet.js', 'leaflet.css']) fs.copyFileSync(path.join(lf, f), path.join(www, 'vendor/leaflet', f));
fs.cpSync(path.join(lf, 'images'), path.join(www, 'vendor/leaflet/images'), { recursive: true });

const left = fs.readdirSync(www).filter(f => f.endsWith('.html')).filter(f => /unpkg\.com/.test(fs.readFileSync(path.join(www, f), 'utf8')));
if (left.length) console.warn('Warning: other unpkg references remain in', left.join(', '));
console.log('www/ ready.');
